package com.hbm.entity.mob.maskman;
import com.hbm.entity.projectile.EntityBulletBaseNT;import com.hbm.exposure.*;import java.util.*;import net.minecraft.core.registries.Registries;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;import net.neoforged.bus.api.IEventBus;import net.neoforged.fml.ModContainer;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.registries.*;
public final class MaskManContent {
 private static final DeferredRegister<EntityType<?>> ENTITIES=DeferredRegister.create(Registries.ENTITY_TYPE,"hbm");private static final DeferredRegister.Items ITEMS=DeferredRegister.createItems("hbm");
 public static final DeferredHolder<EntityType<?>,EntityType<MaskMan>> MASKMAN=ENTITIES.register("entity_mob_mask_man",()->EntityType.Builder.<MaskMan>of(MaskMan::new,MobCategory.MONSTER).sized(2,5).fireImmune().clientTrackingRange(5).updateInterval(3).build("hbm:entity_mob_mask_man"));
 public static final DeferredHolder<EntityType<?>,EntityType<EntityBulletBaseNT>> NT_BULLET=ENTITIES.register("entity_bullet_mk3",()->EntityType.Builder.<EntityBulletBaseNT>of(EntityBulletBaseNT::new,MobCategory.MISC).sized(.5F,.5F).clientTrackingRange(16).updateInterval(1).setShouldReceiveVelocityUpdates(false).noSave().build("hbm:entity_bullet_mk3"));
 public static final DeferredItem<Item> COIN=ITEMS.register("coin_maskman",()->new com.hbm.item.CustomLoreItem(new Item.Properties().rarity(Rarity.UNCOMMON),null,"coin_maskman",false));public static final DeferredItem<BottledCloudItem> CLOUD=ITEMS.register("bottled_cloud",BottledCloudItem::new);public static final DeferredItem<net.neoforged.neoforge.common.DeferredSpawnEggItem> EGG=ITEMS.register("entity_mob_mask_man_spawn_egg",()->new net.neoforged.neoforge.common.DeferredSpawnEggItem(MASKMAN,0x818572,0xC7C1B7,new Item.Properties()));
 public static void register(IEventBus bus,ModContainer container){MaskManConfig.register(container);ENTITIES.register(bus);ITEMS.register(bus);bus.addListener((net.neoforged.neoforge.event.entity.EntityAttributeCreationEvent event)->event.put(MASKMAN.get(),MaskMan.attributes().build()));bus.addListener((net.neoforged.neoforge.event.BuildCreativeModeTabContentsEvent event)->{if(event.getTabKey()==CreativeModeTabs.SPAWN_EGGS)event.accept(EGG.get());});bus.addListener(MaskManDashPackets::register);HbmExposure.addProtection(new ExposureProtection(){@Override public boolean radiationImmune(LivingEntity entity){return entity instanceof MaskMan;}});NeoForge.EVENT_BUS.register(MaskManSpawn.class);NeoForge.EVENT_BUS.register(CloudDashRuntime.class);}
 public static List<ItemStack> creativeStacks(String tab){return tab.equals("consumable")?List.of(new ItemStack(COIN.get()),new ItemStack(CLOUD.get())):List.of();}private MaskManContent(){}
}
